param([string]$BaseUrl="http://127.0.0.1:8000",[int]$ProjectId=1)
$ErrorActionPreference="Stop"
function Session([string]$scope){Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/auth/local/demo-session" -ContentType "application/json" -Body (@{scope=$scope}|ConvertTo-Json -Compress)}
function Post([string]$path,[hashtable]$payload,[hashtable]$headers){Invoke-RestMethod -Method Post -Uri "$BaseUrl$path" -Headers $headers -ContentType "application/json" -Body ($payload|ConvertTo-Json -Depth 12 -Compress)}
$hq=Session hq;$agency=Session agency;$client=Session client;$hh=@{Authorization="Bearer $($hq.token)"};$ah=@{Authorization="Bearer $($agency.token)"};$ch=@{Authorization="Bearer $($client.token)"}
$stamp=Get-Date -Format "yyyyMMddHHmmssfff";$root="/api/v1/factory-platform/projects/$ProjectId/reputation";$m=Post "$root/mentions" @{public_reference="https://public.example/mention-$stamp";channel="media";sentiment="neutral";observed_on="2026-08-06"} $hh;$a=Post "$root/mentions/$($m.id)/assessments" @{assessment_manifest=@{summary="observed";response_required=$false}} $hh;$a=Post "$root/assessments/$($a.id)/verify" @{expected_revision=$a.revision;reference="REPUTATION-VERIFY-$stamp"} $ah;$r=Post "$root/assessments/$($a.id)/releases" @{target="marketing-owner";response_manifest=@{action="owner-review";automatic_public_reply=$false};rollback_reference="REPUTATION-ROLLBACK-$stamp"} $hh;$r=Post "$root/releases/$($r.id)/approve" @{expected_revision=$r.revision;reference="REPUTATION-APPROVE-$stamp"} $ah;$r=Post "$root/releases/$($r.id)/acknowledge" @{expected_revision=$r.revision;reference="REPUTATION-RECEIPT-$stamp"} $ch;$w=Invoke-RestMethod -Method Get -Uri "$BaseUrl$root" -Headers $hh;[pscustomobject]@{release_available=$r.available;availability=$w.availability.status;fabricated_review_or_endorsement=$w.contract.fabricated_review_or_endorsement;automatic_public_reply=$w.contract.automatic_public_reply;evidence_count=$w.evidence.Count}|ConvertTo-Json
